/bin/bash -lc "cat > src/App.tsx <<'EOF'
import { Button, ToasterComponent, ToasterProvider, toaster } from '@gravity-ui/uikit';

const NOTIFICATION_NAME = 'request-success-notification';

export function App() {
  const showNotification = () => {
    if (toaster.has(NOTIFICATION_NAME)) {
      toaster.remove(NOTIFICATION_NAME);
    }

    toaster.add({
      name: NOTIFICATION_NAME,
      theme: 'success',
      title: 'Уведомление',
      content: 'Действие выполнено успешно.',
      autoHiding: 4000,
      isClosable: true,
    });
  };

  return (
    <ToasterProvider toaster={toaster}>
      <Button
        view=\"accent\"
        size=\"m\"
        onClick={showNotification}
        style={{ position: 'fixed', right: 24, bottom: 24 }}
      >
        Показать уведомление
      </Button>
      <ToasterComponent />
    </ToasterProvider>
  );
}
EOF
npm run build
git diff -- src/App.tsx"

/bin/bash -lc "node <<'NODE'
const { readFileSync, writeFileSync } = require('node:fs');
const path = 'src/App.tsx';
let text = readFileSync(path, 'utf8');
text = text.replace(\"import { Button, ToasterComponent, ToasterProvider, toaster } from '@gravity-ui/uikit';\", \"import { Button, ToasterComponent, ToasterProvider } from '@gravity-ui/uikit';\\nimport { toaster } from '@gravity-ui/uikit/toaster-singleton';\");
text = text.replace('view=\"accent\"', 'view=\"action\"');
writeFileSync(path, text);
NODE
npm run build"
